INSERT INTO products (name, slug, category, description, price, compare_at_price, stock, sizes, colors, image_key, featured) VALUES
('Nike Air Zoom Pegasus 41', 'nike-air-zoom-pegasus-41', 'Running', 'Chiến mã chạy bộ hàng ngày thế hệ mới với bộ đôi túi khí Air Zoom trước sau kết hợp bọt đệm ReactX hoàn toàn mới, tăng 13% độ hoàn trả năng lượng so với thế hệ trước. Phom ôm chân, phù hợp cự ly 5km - 21km.', 3490000, 3890000, 28, '["39","40","41","42","43","44"]', '["Trắng Phối Cam Volt","Đen Bạc"]', 'products/ef07f4af-f26d-46cf-b134-2db1d920e5a1.jpg', 1),
('Nike ZoomX Vaporfly 3', 'nike-zoomx-vaporfly-3', 'Running', 'Siêu giày đua marathon đỉnh cao thế giới. Tấm đĩa sợi carbon Flyplate nguyên khối đặt giữa hai lớp bọt siêu nhẹ ZoomX, mang lại lực đẩy về phía trước tối đa để bứt phá kỷ lục cá nhân (PR).', 5890000, 6490000, 14, '["40","41","42","43","44"]', '["Hồng Neon Bạc","Trắng Ngọc"]', 'products/49c4e8c0-06d5-4dd0-932c-78b39de6e9e2.jpg', 1),
('Nike Invincible 3', 'nike-invincible-3', 'Running', 'Vua đệm êm giảm chấn bảo vệ khớp gối. Khối lượng bọt ZoomX cực dày được đặt trên đế bè rộng giúp duy trì sự thăng bằng tối ưu, lý tưởng cho những ngày chạy phục hồi đường dài.', 4290000, 4790000, 20, '["40","41","42","43","44","45"]', '["Đen Trắng Phối Đỏ","Xám Bạc"]', 'products/7351f872-5b0d-4454-9202-a80fd9cd9199.jpg', 0),
('Nike Air Zoom Vomero 17', 'nike-air-zoom-vomero-17', 'Running', 'Sự kết hợp hoàn hảo giữa độ êm ái của bọt ZoomX bên trên và bọt Cushlon 3.0 bền bỉ bên dưới. Êm ái vượt trội, lưỡi gà và cổ giày đệm mút sang trọng.', 3890000, 4390000, 18, '["39","40","41","42","43"]', '["Xanh Navy Bạc","Trắng Platinum"]', 'products/ed7bfc3b-16c1-4769-8e18-5b6a95a20a7d.jpg', 0),
('Nike Dunk Low Retro Panda', 'nike-dunk-low-retro-panda', 'Lifestyle', 'Biểu tượng phong cách đường phố toàn cầu. Phối màu Trắng Đen (Panda) kinh điển phối cùng chất da trơn dẻo dai, dễ dàng mix đồ từ quần jeans, ống thụng đến short thể thao.', 3190000, 3590000, 35, '["38","39","40","41","42","43","44"]', '["Trắng Đen (Panda)"]', 'products/88c433f2-11b1-44f7-b1ab-e40408fd5506.jpg', 1),
('Nike Air Force 1 07 Triple White', 'nike-air-force-1-07-white', 'Lifestyle', 'Đôi sneaker trắng huyền thoại bất tử của Nike từ năm 1982. Đệm khí Nike Air ẩn trong gót, thân giày da thật viền may tinh xảo, tab kim loại AF-1 trên dây buộc sáng bóng.', 2890000, 3290000, 30, '["38","39","40","41","42","43","44"]', '["All White (Trắng Tinh Khôi)"]', 'products/7b0723bc-e788-4b59-bf15-bc93722ddfa5.jpg', 0),
('Nike Pegasus Trail 4 GORE-TEX', 'nike-pegasus-trail-4-gtx', 'Outdoor', 'Giày chạy địa hình dã ngoại chống nước tuyệt đối với màng GORE-TEX cao cấp. Đệm bọt React êm ái linh hoạt khi chuyển đổi từ đường nhựa thành phố sang đường mòn lầy lội.', 3990000, 4490000, 16, '["40","41","42","43","44"]', '["Xám Than Cam Rực","Đen Tuyển"]', 'products/d15c533c-7cba-4f62-a21e-c64aedaa7bba.jpg', 0),
('Adidas Samba OG Classic', 'adidas-samba-og-classic', 'Lifestyle', 'Biểu tượng văn hóa thời trang bóng đá Terrace retro từ Đức. Thân da mềm cao cấp phối mũi da lộn chữ T kinh điển, đế cao su gum tự nhiên bám đường và mang phong cách trường tồn.', 2790000, 3190000, 32, '["39","40","41","42","43"]', '["Trắng Sọc Đen Mũi Xám","Đen Sọc Trắng"]', 'products/3dc3f640-b618-4aef-97a5-16f0926a64b2.jpg', 1),
('Adidas Gazelle Indoor', 'adidas-gazelle-indoor', 'Lifestyle', 'Bản nâng cấp đình đám với đế cao su gum trong suốt bao bọc quanh thân giày. Chất liệu da lộn mềm mịn thượng hạng với các tông màu vintage cuốn hút mọi ánh nhìn.', 2990000, 3390000, 22, '["38","39","40","41","42","43"]', '["Xanh Lá Đậm Sọc Trắng","Xanh Biển Nhạt"]', 'products/d343dd58-eeba-44a9-b072-4419c7808c1f.jpg', 0),
('Adidas Superstar 82 Originals', 'adidas-superstar-82-originals', 'Lifestyle', 'Huyền thoại mũi sò Shell-toe xuất hiện trên mọi sàn diễn hip-hop và bóng rổ từ 1969. Chất da hạt dày dặn, viền 3 sọc răng cưa đục lỗ thông khí thoáng mát.', 2590000, 2990000, 25, '["39","40","41","42","43","44"]', '["Trắng Sọc Đen Gót Đen"]', 'products/80b2ba69-7df6-4c35-8e38-d94b7b46d0b8.jpg', 0),
('Adidas Ultraboost Light', 'adidas-ultraboost-light', 'Running', 'Thế hệ đệm bọt Light BOOST nhẹ hơn 30% so với Boost truyền thống, mang lại bước chạy siêu êm ái, bồng bềnh và trả lực liên tục. Thân dệt Primeknit ôm khít như đôi tất.', 4190000, 4890000, 20, '["40","41","42","43","44","45"]', '["Trắng Phối Đỏ Cam","Đen Core Black"]', 'products/1329aa3c-5dbd-49a2-bf97-618baf7e6964.jpg', 1),
('Adidas Adizero Adios Pro 3', 'adidas-adizero-adios-pro-3', 'Running', 'Vũ khí vô địch các giải World Marathon Majors. Trang bị hệ thống thanh năng lượng sợi carbon ENERGYRODS 2.0 mô phỏng cấu trúc xương ngón chân cùng 2 tầng bọt Lightstrike Pro siêu nảy.', 5990000, 6590000, 12, '["40","41","42","43","44"]', '["Xanh Ngọc Solar Red","Trắng Bạc"]', 'products/9881139a-fb8a-4adc-8f86-87920fd8e6b3.jpg', 1),
('Adidas Adizero Boston 12', 'adidas-adizero-boston-12', 'Running', 'Mẫu giày luyện tập tốc độ (tempo / interval) và cự ly dài ưa chuộng nhất. Đệm kép kết hợp Lightstrike Pro êm nảy và Lightstrike 2.0 bền chắc cùng thanh carbon Energyrods trợ lực.', 3790000, 4290000, 19, '["39","40","41","42","43"]', '["Trắng Sọc Đen Neon","Xanh Dương Đậm"]', 'products/a9dbf73b-3357-43aa-99f5-c2077e70abe2.jpg', 0),
('Adidas Terrex Free Hiker 2 GORE-TEX', 'adidas-terrex-free-hiker-2-gtx', 'Outdoor', 'Giày dã ngoại trekking leo núi đỉnh cao với đế đệm Boost êm ái trên từng mỏm đá gồ ghề. Đế ngoài cao su Continental siêu bám địa hình trơn ướt cùng màng GORE-TEX chống nước hoàn toàn.', 4490000, 5190000, 15, '["40","41","42","43","44"]', '["Xám Bạc Đen Vàng Rừng","Xanh Rêu Đen"]', 'products/27dd3418-51b2-44ce-bf5d-2b8a8924f30e.jpg', 0),
('New Balance 550 White Grey', 'new-balance-550-white-grey', 'Lifestyle', 'Tái hiện mẫu giày bóng rổ cổ thấp vintage năm 1989. Thiết kế dad shoes thanh lịch, chất da phối viền xám nhẹ nhàng, logo N dập nổi đặc trưng dễ dàng mix đồ thanh lịch.', 2990000, 3490000, 26, '["39","40","41","42","43","44"]', '["Trắng Xám Bạc","Trắng Xanh Navy"]', 'products/ac357fb3-0b0b-45d1-81bc-3dc1e2b80ac8.jpg', 1),
('New Balance 530 Steel Grey', 'new-balance-530-steel-grey', 'Lifestyle', 'Cơn sốt giày retro runner đầu những năm 2000. Thân giày bằng lưới mắt to siêu thoáng khí kết hợp các dải da bóng sắc nét, đế đệm ABZORB hấp thụ chấn động mềm mại khi di chuyển.', 2690000, 3090000, 30, '["38","39","40","41","42","43"]', '["Xám Bạc Ánh Kim","Trắng Phối Xanh Dương"]', 'products/ce6de2f8-ad8d-455e-8714-7f3c722af26d.jpg', 1),
('New Balance 2002R Protection Pack', 'new-balance-2002r-protection-pack', 'Lifestyle', 'Thiết kế viền da lộn rách xước có chủ đích (deconstructed) độc nhất vô nhị. Trang bị công nghệ đế đệm N-ergy cao cấp và ABZORB SBS giảm sốc vượt trội dưới gót chân.', 3990000, 4590000, 18, '["40","41","42","43","44"]', '["Xám Khói Rain Cloud","Đen Phantom"]', 'products/a6bc48ec-e703-4baa-95d3-183dff63d1ff.jpg', 1),
('New Balance 1906R Metallic Silver', 'new-balance-1906r-metallic-silver', 'Lifestyle', 'Mẫu giày Tech-runner mang hơi thở tương lai. Khung nhựa gót TPU Stability Web hỗ trợ vòm bàn chân, hệ thống dây khóa N-Lock giữ mu bàn chân ổn định trên từng sải bước.', 3890000, 4390000, 17, '["39","40","41","42","43"]', '["Bạc Metallic Ánh Vàng","Trắng Phối Xanh Lá"]', 'products/43036aa6-184d-4e73-ae3e-d6d3d69e06c3.jpg', 0),
('New Balance Fresh Foam X 1080v13', 'new-balance-fresh-foam-x-1080v13', 'Running', 'Đỉnh cao êm ái của New Balance với khối bọt Fresh Foam X thế hệ mới nhất, mang lại cảm giác tiếp đất mềm như kẹo dẻo và chuyển động lăn bàn chân siêu mượt mà.', 4390000, 4890000, 20, '["40","41","42","43","44","45"]', '["Xanh Biển Phối Trắng","Đen Bạc"]', 'products/c938c39e-dcaf-4af4-a8f0-8f46fad02321.jpg', 0),
('New Balance FuelCell Rebel v4', 'new-balance-fuelcell-rebel-v4', 'Running', 'Giày chạy tốc độ không cần đĩa carbon nhẹ nhất phân khúc với bọt đệm FuelCell pha PEBA siêu nảy. Thiết kế mũi bè chuẩn phom bàn chân người Châu Á, bứt tốc độ cực nhạy.', 3590000, 3990000, 16, '["39","40","41","42","43","44"]', '["Trắng Phối Đỏ Neon","Xanh Da Trời"]', 'products/97e23168-e769-4023-b872-0231bd5fae60.jpg', 0),
('New Balance Fresh Foam X Hierro v8', 'new-balance-fresh-foam-x-hierro-v8', 'Outdoor', 'Chiến binh việt dã địa hình với đế ngoài cao su Vibram Megagrip bám dính chắc chắn trên mọi cung đường bùn đất, đá dăm kết hợp đệm Fresh Foam X bảo vệ khớp chân.', 3790000, 4290000, 15, '["40","41","42","43","44"]', '["Xám Đất Nung Phối Đen","Xanh Rêu"]', 'products/4357defd-4891-4eb0-8d54-f9effa7b5f73.jpg', 0),
('Puma Palermo Leather Gum', 'puma-palermo-leather-gum', 'Lifestyle', 'Hồi sinh phong cách bóng đá Terrace thập niên 80 từ bờ biển nước Ý. Chất da tự nhiên mềm mại phối mũi da lộn, đế gum retro và tag da vàng kim chữ Palermo sang trọng.', 2490000, 2890000, 24, '["39","40","41","42","43"]', '["Xanh Cốm Trắng","Hồng Pastel Phối Trắng"]', 'products/6e8aa571-5e9c-4af2-b0cb-2a84b0f275be.jpg', 1),
('Puma Suede Classic XXI', 'puma-suede-classic-xxi', 'Lifestyle', 'Đôi giày da lộn bất tử của văn hóa đường phố và b-boy breakdance từ năm 1968. Da lộn nhung cao cấp dày dặn, dải Formstrip uốn lượn bên sườn tạo dấu ấn nhận diện không thể nhầm lẫn.', 1990000, 2390000, 28, '["38","39","40","41","42","43","44"]', '["Đen Sọc Trắng","Đỏ Sọc Trắng"]', 'products/3fde621a-0f48-4aff-9bd2-ebaa5064b07e.jpg', 0),
('Puma Army Trainer Retro', 'puma-army-trainer-retro', 'Lifestyle', 'Thiết kế nguyên bản của dòng giày huấn luyện quân đội Đức (German Army Trainer). Tối giản, thanh lịch với da trơn trắng và mũi da lộn chữ T xám, đế bệt bền bỉ.', 2290000, 2690000, 20, '["39","40","41","42","43"]', '["Trắng Xám Đế Gum"]', 'products/27558066-0def-4108-a63d-12f28e701ace.jpg', 0),
('Puma Deviate Nitro 2 Carbon', 'puma-deviate-nitro-2-carbon', 'Running', 'Giày chạy bộ trợ lực đĩa carbon composite INNOPLATE cao cấp kết hợp lớp bọt bơm khí nitơ Nitro Elite siêu nhẹ và nảy. Độ bám đường đỉnh cao với đế cao su PUMAGRIP bám cả trên mặt đường ướt.', 3990000, 4590000, 16, '["40","41","42","43","44"]', '["Cam Neon Phối Đen","Trắng Bạc"]', 'products/2229f69f-9288-4c66-b028-535da7f566c3.jpg', 1),
('Puma Velocity Nitro 3', 'puma-velocity-nitro-3', 'Running', 'Được đánh giá là đôi giày chạy bộ hàng ngày đáng tiền nhất. Đệm bọt NITRO êm ái, nhẹ và êm, độ bền vượt 1000km, phù hợp cho cả người mới chạy và vận động viên cự ly dài.', 2990000, 3490000, 22, '["39","40","41","42","43","44"]', '["Xanh Dương Điện Tử","Đen Phối Vàng Chanh"]', 'products/f6f69d84-d8f5-4f22-8279-90b07c4f28a4.jpg', 0),
('Puma MB.03 Toxic LaMelo Ball', 'puma-mb03-toxic-lamelo-ball', 'Basketball', 'Giày bóng rổ signature phá cách của ngôi sao NBA LaMelo Ball. Đồ họa vết cào xé độc đáo, đệm bọt NITRO bùng nổ sức bật và đế ngoài cao su siêu bám sân sàn gỗ hoặc bê tông.', 3390000, 3890000, 15, '["40","41","42","43","44","45"]', '["Tím Neon Độc Lạ","Trắng Đen"]', 'products/dc352729-2950-4681-bea1-efa2cee46c5b.jpg', 0),
('Puma Voyage Nitro 3 Trail', 'puma-voyage-nitro-3-trail', 'Outdoor', 'Giày dã ngoại địa hình bám chắc mọi bề mặt sỏi đá với hợp chất cao su PUMAGRIP-ATR đa hướng. Hệ thống dây buộc OPTIFIT ôm chắc mu bàn chân khi đổ dốc an toàn.', 3290000, 3790000, 14, '["40","41","42","43","44"]', '["Đen Phối Xanh Olive","Xám Bạc"]', 'products/683cbe68-1b71-4fcd-aef4-6d0421d573b0.jpg', 0),
('Salomon XT-6 Black Phantom', 'salomon-xt-6-black-phantom', 'Outdoor', 'Ngôi sao dẫn đầu trào lưu thời trang Gorpcore toàn cầu từ dãy núi Alps nước Pháp. Khung đế Agile Chassis System (ACS) chống vặn xoắn gót chân, màng ép nhiệt TPU bền bỉ và dây rút Quicklace tiện lợi.', 4690000, 5290000, 20, '["40","41","42","43","44"]', '["Đen Toàn Diện (Black Phantom)","Trắng Be Bạc"]', 'products/eb2154de-083f-4113-b0f9-afc7c5f50926.jpg', 1),
('Salomon ACS Pro Advanced Metal', 'salomon-acs-pro-advanced-metal', 'Outdoor', 'Thiết kế Techwear tương lai mang tính kỹ thuật cao với hệ thống lồng thông gió Kurim hai bên hông giày. Khung đỡ Kurim giữ vững bàn chân khi di chuyển ở mọi địa hình gồ ghề.', 4990000, 5590000, 15, '["40","41","42","43","44"]', '["Kim Loại Bạc Trắng","Đen Tuyển"]', 'products/77b4e4f3-02d5-43f1-b7eb-c6f2424de641.jpg', 1),
('Salomon Speedcross 6 Grip', 'salomon-speedcross-6-grip', 'Outdoor', 'Vua bám bùn đất của làng chạy việt dã. Gai đế Chevron hình chữ V sắc nhọn găm sâu vào đất mềm và bùn lầy, thân giày kháng xé sợi ripstop và bảo vệ ngón chân chống va đập.', 3690000, 4190000, 18, '["39","40","41","42","43"]', '["Đen Đỏ Rực","Xanh Biển Phối Đen"]', 'products/89049584-34d4-4474-afd9-0bd38f387559.jpg', 0),
('Salomon Pulsar Trail Pro', 'salomon-pulsar-trail-pro', 'Outdoor', 'Giày việt dã tốc độ trang bị đĩa Energy Blade bằng sợi tổng hợp đẩy người chạy lao về phía trước, bọt Energy Foam siêu nảy giúp giữ sức trên các cự ly chạy trail 50km - 100km.', 3890000, 4390000, 14, '["40","41","42","43","44"]', '["Đỏ Cam Hoàng Hôn","Trắng Bạc"]', 'products/a757831e-c2d3-453a-a591-08ae9dd897b0.jpg', 0),
('Salomon XT-4 OG Fiery Red', 'salomon-xt-4-og-fiery-red', 'Outdoor', 'Bản phối màu gradient rực lửa nguyên bản từ lịch sử đường mòn Salomon. Khung đế nâng đỡ toàn phần bền bỉ như áo giáp, đế Contagrip kiểm soát trơn trượt trên đá ướt.', 4590000, 5190000, 16, '["40","41","42","43","44"]', '["Đỏ Rực Phối Vàng Cam","Trắng Đen"]', 'products/e73cb6df-0c1c-4f46-afa9-eadb3f68bec2.jpg', 0),
('Salomon X Ultra 4 GORE-TEX', 'salomon-x-ultra-4-gtx', 'Outdoor', 'Đôi giày trekking dã ngoại bán chạy nhất của Salomon. Công nghệ ADV-C Chassis khóa chặt khớp mắt cá ngoài, bảo vệ bàn chân không bị lật khi bước qua đá gồ ghề nguy hiểm.', 3790000, 4290000, 19, '["40","41","42","43","44"]', '["Đen Xám Bạc","Xanh Rêu Xám"]', 'products/f2a52042-695b-48b2-a714-706471c15129.jpg', 0),
('Salomon Speedverse PRG', 'salomon-speedverse-prg', 'Lifestyle', 'Sự giao thoa táo bạo giữa giày địa hình và thời trang dạo phố đương đại. Các đường vân uốn lượn sắc bén trên thân giày phối da và lưới dệt 3D cao cấp.', 3990000, 4490000, 15, '["39","40","41","42","43"]', '["Trắng Ngà Phối Xám","Đen Tuyền"]', 'products/94c5ca76-01c1-4b80-9386-99debc9a36de.jpg', 0),
('Asics Gel-Nimbus 26 PureGEL', 'asics-gel-nimbus-26-puregel', 'Running', 'Được mệnh danh là đôi giày chạy êm nhất thế giới của Nhật Bản. Công nghệ PureGEL giấu bên trong gót mềm hơn 65% so với gel truyền thống kết hợp bọt FF BLAST+ ECO bảo vệ đầu gối tuyệt đối.', 4190000, 4690000, 25, '["40","41","42","43","44","45"]', '["Xanh Biển Phối Trắng","Đen Platinum"]', 'products/50494bfb-f0f9-4092-91c6-6a34e19a199a.jpg', 1),
('Asics Gel-Kayano 31 4D Guidance', 'asics-gel-kayano-31-4d-guidance', 'Running', 'Vua của dòng giày ổn định và chống sụp vòm chân. Hệ thống 4D GUIDANCE SYSTEM tự động điều chỉnh thích ứng theo từng chuyển động mỏi của bàn chân, giữ thăng bằng hoàn hảo.', 4390000, 4990000, 22, '["40","41","42","43","44","45"]', '["Xám Bạc Băng Giá","Đen Phối Vàng Đồng"]', 'products/7a266c77-27cd-437c-8749-d5d8f630f6ba.jpg', 1),
('Asics Novablast 4 Trampoline', 'asics-novablast-4-trampoline', 'Running', 'Thiết kế đế hình học bạt nhún trampoline độc quyền mang lại cảm giác nảy bật tưng bừng trên từng bước chạy. Trọng lượng siêu nhẹ với bọt đệm FF BLAST+ ECO tái tạo năng lượng dồi dào.', 3690000, 4190000, 28, '["39","40","41","42","43","44"]', '["Trắng Phối Xanh Neon","Đen Xám Khói"]', 'products/c83f43f6-81e0-4d68-b154-1509148cfb5b.jpg', 1),
('Asics GT-2000 12 Stability', 'asics-gt-2000-12-stability', 'Running', 'Sự cân bằng hoàn hảo giữa độ nhẹ linh hoạt và khả năng trợ lực cổ chân với công nghệ 3D GUIDANCE SYSTEM, bền bỉ và cực kỳ đáng tin cậy cho những buổi chạy hằng ngày.', 3390000, 3890000, 18, '["40","41","42","43","44"]', '["Xanh Navy Trắng","Xám Đen"]', 'products/6b8c2245-6e57-400c-adb2-9a1f0c4c45e6.jpg', 0),
('Asics Gel-NYC Cream Oyster Grey', 'asics-gel-nyc-cream-oyster-grey', 'Lifestyle', 'Hòa quyện di sản thiết kế cổ điển GEL-NIMBUS 3 và GEL-CUMULUS 16 thành tuyệt tác thời trang retro runner đương đại. Đệm GEL lộ ra ở cả gót và mũi tạo nét cá tính khác biệt.', 3490000, 3990000, 20, '["39","40","41","42","43","44"]', '["Kem Xám Bạc (Cream Oyster)","Trắng Phối Xanh Rêu"]', 'products/3fff48c9-5b7e-4c7a-be79-68b00c15919d.jpg', 0),
('Asics Metaspeed Sky Paris Carbon', 'asics-metaspeed-sky-paris-carbon', 'Running', 'Siêu phẩm giày đua marathon kỷ lục tại Thế vận hội Paris. Bọt FF TURBO PLUS siêu nẩy kết hợp đĩa carbon mở rộng giúp các chân chạy sải bước dài hơn mà tốn ít sức lực nhất.', 6290000, 6990000, 10, '["40","41","42","43","44"]', '["Đỏ Cam Lửa Paris","Trắng Bạc"]', 'products/e526dc35-ce13-488a-ab1c-a73ba1fed94f.jpg', 1),
('Asics Gel-Trabuco 12 Trail', 'asics-gel-trabuco-12-trail', 'Outdoor', 'Đôi giày việt dã bảo vệ bàn chân toàn diện trên cung đường đá dăm với tấm chống đá nhọn (Rock Protection Plate) và cao su ASICSGRIP bám dính siêu hạng trên đá ướt.', 3590000, 4090000, 15, '["40","41","42","43","44"]', '["Xanh Đen Cam","Xám Rừng"]', 'products/c77a4b34-38e0-4c15-8b50-57df929a2fac.jpg', 0),
('Onitsuka Tiger Mexico 66 White Blue Red', 'onitsuka-tiger-mexico-66-white-blue-red', 'Lifestyle', 'Huyền thoại sọc hổ bất tử từ Thế vận hội Mexico 1968. Thân giày bằng da bò mềm mại ôm gọn bàn chân thanh mảnh, lưỡi gà chéo sau gót kinh điển mang phong cách hoài cổ xứ Phù Tang.', 2890000, 3390000, 30, '["38","39","40","41","42","43"]', '["Trắng Sọc Xanh Đỏ","Trắng Sọc Đen"]', 'products/ab5c4eb4-3937-463f-a17b-7fce6c1a7885.jpg', 1),
('Onitsuka Tiger Mexico 66 SD Leather', 'onitsuka-tiger-mexico-66-sd-leather', 'Lifestyle', 'Phiên bản kỷ niệm Super Deluxe (SD) chế tác từ da thuộc thượng hạng Nhật Bản. Bổ sung đệm bọt amplifoam ở gót chân giúp êm ái hơn hẳn phiên bản truyền thống.', 3790000, 4290000, 18, '["39","40","41","42","43"]', '["Trắng Ngà Da Mềm","Đen Sọc Bạc"]', 'products/30dab3fc-87b9-4d05-a5c8-18ae8218b45d.jpg', 0),
('Onitsuka Tiger Serrano Retro Gold', 'onitsuka-tiger-serrano-retro-gold', 'Lifestyle', 'Lấy cảm hứng từ giày đinh điền kinh thập niên 70 với dáng mũi giày cong nhẹ thanh thoát. Thân vải dù siêu nhẹ phối da lộn hai bên mang lại cảm giác nhẹ bẫng khi di chuyển.', 2390000, 2790000, 22, '["38","39","40","41","42","43"]', '["Vàng Ánh Kim Sọc Xanh","Xanh Navy Sọc Trắng"]', 'products/16988171-7f00-4c2a-87de-854a1c2c88f6.jpg', 0),
('Onitsuka Tiger Tokuten Indoor Gum', 'onitsuka-tiger-tokuten-indoor-gum', 'Lifestyle', 'Phong cách giày sân bóng trong nhà cổ điển với chất da lộn mịn bao bọc mũi giày và đế cao su gum tự nhiên dày dặn, đang là một trong những mẫu giày hot trend được giới trẻ săn đón.', 2690000, 3090000, 25, '["39","40","41","42","43"]', '["Trắng Sọc Đen Đế Gum","Xám Bạc"]', 'products/3cdb9ea0-da84-4fc3-b332-fca4c927424f.jpg', 1),
('Onitsuka Tiger GSM Court Vintage', 'onitsuka-tiger-gsm-court-vintage', 'Lifestyle', 'Viết tắt của Game - Set - Match, mẫu giày tennis cổ điển thập niên 80. Các đường dập lỗ ziczac trên thân da trơn thanh lịch, đế phẳng nâng niu bàn chân suốt cả ngày dài.', 2590000, 2990000, 20, '["39","40","41","42","43","44"]', '["Trắng Sọc Xanh Hunter","Trắng Sọc Đỏ Rượu"]', 'products/e6e8a683-45dc-4093-83ba-b8471cc17646.jpg', 0),
('Onitsuka Tiger Delegation EX Chunky', 'onitsuka-tiger-delegation-ex-chunky', 'Lifestyle', 'Bản phối hiện đại đế dày chunky thời thượng cải tiến từ giày của đoàn thể thao Nhật Bản năm 1964. Tích hợp bọt đệm FLYTEFOAM PROPEL siêu êm ái tăng chiều cao tinh tế.', 3490000, 3990000, 16, '["38","39","40","41","42","43"]', '["Trắng Phối Đỏ Xanh","Đen Nguyên Bản"]', 'products/5ce489a6-3846-4ec5-ac75-82d7057936ce.jpg', 0),
('Onitsuka Tiger Mexico 66 Yellow Kill Bill', 'onitsuka-tiger-mexico-66-yellow-kill-bill', 'Lifestyle', 'Phối màu vàng sọc đen biểu tượng gắn liền với Lý Tiểu Long và bộ phim Kill Bill huyền thoại. Điểm nhấn nổi bật độc nhất vô nhị làm bừng sáng mọi bộ trang phục dạo phố.', 2990000, 3490000, 26, '["38","39","40","41","42","43"]', '["Vàng Sọc Đen (Kill Bill)"]', 'products/ab5c4eb4-3937-463f-a17b-7fce6c1a7885.jpg', 1),
('Mizuno Wave Rider 28 Enerzy', 'mizuno-wave-rider-28-enerzy', 'Running', 'Dòng giày chạy biểu tượng suốt gần 30 năm qua của Nhật Bản. Đĩa đệm cơ học Wave độc quyền phân tán lực chấn động kết hợp bọt MIZUNO ENERZY NXT đàn hồi siêu nảy và bền bỉ vượt trội.', 3590000, 4090000, 24, '["39","40","41","42","43","44"]', '["Xanh Dương Bạc","Trắng Xám"]', 'products/6d3003ed-20dd-4add-b355-023292533529.jpg', 1),
('Mizuno Wave Inspire 20 Support', 'mizuno-wave-inspire-20-support', 'Running', 'Dành riêng cho những người có vòm chân bẹt và cổ chân dễ bị lật trong. Đĩa Wave bất đối xứng tăng cường độ cứng ở phía má trong giúp giữ thẳng trục mắt cá chân an toàn.', 3490000, 3990000, 18, '["40","41","42","43","44"]', '["Xanh Đen Phối Cam","Xám Platinum"]', 'products/964029b1-f11b-415c-b362-8fc416774f38.jpg', 0),
('Mizuno Wave Skyrise 5 Floating', 'mizuno-wave-skyrise-5-floating', 'Running', 'Cảm giác chạy bồng bềnh như lướt trên mây với công nghệ đệm kép MIZUNO ENERZY CORE siêu êm dưới lòng bàn chân. Dáng giày thanh thoát, vải lưới Jacquard thoáng khí tối đa.', 3290000, 3790000, 20, '["39","40","41","42","43","44"]', '["Trắng Xanh Bạc","Đen Khói"]', 'products/e1865c23-6fef-408b-a35b-de1a83faf675.jpg', 0),
('Mizuno Wave Rebellion Pro 2 Carbon', 'mizuno-wave-rebellion-pro-2-carbon', 'Running', 'Siêu giày đua marathon phá cách với thiết kế vát gót khí động học cực hạn. Đĩa đệm Carbon tăng cường sợi thủy tinh và bọt Enerzy Lite+ giúp guồng chân xoay nhanh kinh ngạc.', 5590000, 6290000, 12, '["40","41","42","43","44"]', '["Vàng Chanh Phối Tím Neon"]', 'products/552d2491-7451-4d77-a175-7b584384291d.jpg', 1),
('Mizuno Wave Mujin 10 Michelin Trail', 'mizuno-wave-mujin-10-michelin-trail', 'Outdoor', 'Hợp tác đỉnh cao với hãng lốp xe số 1 thế giới Michelin. Hợp chất cao su lốp Michelin bám dính siêu hạng trên bùn ướt và đá trơn trượt cùng đĩa đệm Wave ổn định địa hình hiểm trở.', 3790000, 4290000, 15, '["40","41","42","43","44"]', '["Xanh Rừng Phối Đen","Xám Đất"]', 'products/df309061-d8d0-4305-875d-4c0629be74e4.jpg', 0),
('Mizuno Wave Momentum 3 Court', 'mizuno-wave-momentum-3-court', 'Basketball', 'Giày thi đấu thể thao trong nhà (Bóng chuyền, Bóng rổ, Cầu lông) với thiết kế cổ giày bootie ôm khít mắt cá, đĩa Wave trợ lực bật nhảy và đế không để lại vệt màu trên sàn (Non-marking).', 3390000, 3890000, 16, '["40","41","42","43","44"]', '["Trắng Xanh Neon","Đen Bạc"]', 'products/abee14d0-3ae3-4fbf-9ae1-8bc39c81354c.jpg', 0),
('Mizuno Contender Retro Sport', 'mizuno-contender-retro-sport', 'Lifestyle', 'Mẫu sneaker mang đậm tinh thần hoài cổ thập niên 90 với logo chim Runbird dũng mãnh dập nổi hai bên. Phom dáng đầm chắc, da lộn phối vải lưới cao cấp.', 2490000, 2890000, 20, '["39","40","41","42","43"]', '["Trắng Xám Runbird Đỏ","Xanh Navy Trắng"]', 'products/0107474b-71d2-438e-9ac3-08b16cb4d0d3.jpg', 0),
('Li-Ning Feidian 3.0 Elite Carbon', 'li-ning-feidian-3-elite-carbon', 'Running', 'Vũ khí marathon đỉnh cao càn quét các bục vinh quang. Đĩa đệm Carbon nguyên khối uốn cong toàn phần kết hợp bọt đệm BOOM (bọt béo PEBA ép nhiệt siêu tới hạn) đàn hồi hơn 80%.', 3990000, 4590000, 15, '["39","40","41","42","43","44"]', '["Trắng Phối Cam Cháy","Xanh Lam Neon"]', 'products/5ab74b92-a67f-4352-a55c-1e501a44da9b.jpg', 1),
('Li-Ning Yueying 3 Pro Dual BOOM', 'li-ning-yueying-3-pro-dual-boom', 'Running', 'Dòng giày chạy hàng ngày được ưa chuộng bậc nhất của Li-Ning với 2 tầng bọt BOOM êm ái bảo vệ cổ chân, khung TPU Probar Loc chống vặn xoắn giữa bàn chân vững chãi.', 2790000, 3190000, 22, '["39","40","41","42","43"]', '["Trắng Tím Hologram","Đen Bạc"]', 'products/24b2f188-29ca-4a0a-b12b-f4caa0950215.jpg', 0),
('Li-Ning Super Light 21 Breeze', 'li-ning-super-light-21-breeze', 'Running', 'Dòng giày chạy siêu nhẹ kỷ lục chỉ khoảng 180g mỗi chiếc. Thân giày bằng sợi dệt trong suốt thoáng khí giải nhiệt mùa hè kết hợp đệm bọt BOOM êm nảy.', 2290000, 2690000, 25, '["38","39","40","41","42","43"]', '["Xanh Băng Tuyết","Hồng Cam Bình Minh"]', 'products/08521561-2aeb-4c7e-9b74-6482cf5e6fce.jpg', 0),
('Li-Ning Way of Wade 10 Mint Blossom', 'li-ning-way-of-wade-10-mint-blossom', 'Basketball', 'Siêu phẩm bóng rổ hợp tác cùng huyền thoại NBA Dwyane Wade. Tấm đĩa carbon kéo dài toàn bộ đế, lớp bọt BOOM toàn diện bọc trong khung TPU trong suốt, bám sàn gỗ đỉnh cao.', 4990000, 5690000, 14, '["40","41","42","43","44","45"]', '["Xanh Bạc Hà Mint Blossom","Đen Vàng Kim"]', 'products/5843fb6d-3f30-4ae7-8cc0-ee0beaa94093.jpg', 1),
('Li-Ning YuShuai 18 V2 Streetball', 'li-ning-yushuai-18-v2-streetball', 'Basketball', 'Dòng giày bóng rổ cày sân bê tông nức tiếng bền bỉ suốt 18 thế hệ. Đế cao su TUFF RB chống mài mòn gấp 5 lần cao su thông thường kết hợp đệm BOOM bảo vệ đầu gối khi va chạm.', 2890000, 3390000, 20, '["40","41","42","43","44"]', '["Trắng Đỏ Lửa","Đen Tuyền"]', 'products/e9595dfb-8626-45b1-b997-40edb41776d9.jpg', 0),
('Li-Ning Shadow 2 Double Carbon', 'li-ning-shadow-2-double-carbon', 'Running', 'Thiết kế rỗng ruột tương lai mang tính đột phá với 2 tấm đĩa carbon song song uốn cong tạo thành hệ thống đàn hồi cơ học Jiang Technology, trả lực mạnh mẽ chưa từng có.', 5290000, 5990000, 10, '["40","41","42","43","44"]', '["Trắng Đen Phối Đỏ Neon"]', 'products/042bd9fe-088c-464f-8849-120a8e1986ad.jpg', 1),
('Li-Ning Rouge Rabbit 7 Pro', 'li-ning-rouge-rabbit-7-pro', 'Running', 'Đôi giày chạy quốc dân thế hệ thứ 7 với bọt đệm BOOM nhẹ êm cùng đế ngoài GCR bám ướt cải tiến. Mức giá cực kỳ hợp lý cho người tập chạy bộ và rèn luyện thể thao hàng ngày.', 2190000, 2590000, 26, '["39","40","41","42","43"]', '["Trắng Phối Cam Đào","Xanh Biển Nhạt"]', 'products/35372ffe-d1e7-4a97-bcb8-5cf7979afda7.jpg', 0),
('Anta KT8 Shock The Game Klay Thompson', 'anta-kt8-shock-the-game-klay-thompson', 'Basketball', 'Dòng giày thi đấu đỉnh cao của nhà vô địch NBA Klay Thompson. Thiết kế cổ giày có thể gập xuống thành cổ thấp, đệm NitroEdge nảy cực nhạy kết hợp thanh xoắn 3D carbon nâng đỡ.', 2790000, 3290000, 18, '["40","41","42","43","44"]', '["Xanh Tím Neon Vịnh San Francisco","Trắng Vàng Warriors"]', 'products/65c16077-75be-476c-b3b5-1ec66e5f8d27.jpg', 1),
('Anta KT9 3D Carbon Stabilizer', 'anta-kt9-3d-carbon-stabilizer', 'Basketball', 'Thế hệ thứ 9 với hệ thống ổn định SMART S.A.M hấp thụ đến 95% lực phản hồi khi tiếp đất, khóa gót carbon đa hướng giúp các tay ném giữ thăng bằng tuyệt đối trên không trung.', 3290000, 3790000, 15, '["40","41","42","43","44","45"]', '["Đen Phantom Phối Vàng Kim","Trắng Băng"]', 'products/40d33f2b-3f21-46a4-adef-06dc170345a9.jpg', 0),
('Anta Shock The Game 7 Cement King', 'anta-shock-the-game-7-cement-king', 'Basketball', 'Vua của các trận bóng rổ đường phố ngoại trời. Đế gai sâu cao su xi măng A-Hardcourt RB siêu chống mài mòn, bọc mũi TPU chống va đập ngón chân khi va chạm quyết liệt.', 2390000, 2790000, 22, '["40","41","42","43","44"]', '["Xám Bê Tông Phối Đỏ Lửa","Đen Tím"]', 'products/a1027201-ebad-4607-a711-fcd6309886bb.jpg', 0),
('Anta C202 GT Pro Carbon Racing', 'anta-c202-gt-pro-carbon-racing', 'Running', 'Siêu giày đua marathon đẳng cấp quốc tế của Anta với đĩa carbon 3D ôm trọn vòm chân cùng bọt Nitro siêu nảy đàn hồi đến 84%. Trọng lượng nhẹ chỉ 195g cho sải bước thần tốc.', 4190000, 4790000, 12, '["40","41","42","43","44"]', '["Cam Lửa Bạc","Trắng Xanh Biển"]', 'products/d49f2d63-4982-4733-a073-878fd1e03836.jpg', 1),
('Anta PG7 Nitro Daily Cushion', 'anta-pg7-nitro-daily-cushion', 'Running', 'Đôi giày chạy bộ đệm êm thường ngày ứng dụng công nghệ đệm khí nitơ Nitro Tech thế hệ mới. Đem lại cảm giác mềm mại như giẫm trên thảm cỏ, phù hợp cho người mới bắt đầu.', 2190000, 2590000, 25, '["39","40","41","42","43","44"]', '["Trắng Xám Bạc","Xanh Dương Đậm"]', 'products/53471c6c-836a-4cd9-b881-daa2aef4c922.jpg', 0),
('Anta Mach 4 Speed Training', 'anta-mach-4-speed-training', 'Running', 'Mẫu giày rèn luyện tốc độ (Tempo run) không đĩa carbon được các runner Châu Á đánh giá rất cao. Thân lưới dệt thoáng khí, đệm bọt nảy nhạy bén giúp guồng chân đều nhịp.', 2490000, 2890000, 20, '["39","40","41","42","43"]', '["Trắng Phối Xanh Neon","Đen Đỏ"]', 'products/ebc70d22-8b73-4cdc-b38e-fe77bb69eb97.jpg', 0),
('Anta Walker Retro Casual', 'anta-walker-retro-casual', 'Lifestyle', 'Giày dạo phố retro phong cách casual năng động với mức giá cực kỳ dễ tiếp cận. Thân da tổng hợp phối vải thoáng, đệm êm nâng đỡ bàn chân khi đi bộ nhiều giờ liền.', 1890000, 2290000, 28, '["39","40","41","42","43","44"]', '["Trắng Sọc Xanh Navy","Trắng Toàn Diện"]', 'products/d6618c96-656e-45c9-8050-aa7c824cd13f.jpg', 0);